import React, { useCallback, useEffect, useRef, useState } from "react"

import Shell from "../../components/layout/Shell"
import Panel from "../../components/layout/Panel"
import Breadcrumb from "../../components/ui/Breadcrumb"
import Toast, { useToast } from "../../components/ui/Toast"

import { isConfigured } from "../../data/supabase.js"
import { invalidateRemoteCache } from "../../data/remote.js"
import {
  AdminError,
  addSymbol,
  cancelIngest,
  currentUser,
  getCoverage,
  getDataStatus,
  getJobs,
  getSettings,
  getUniverse,
  isAdmin,
  onAuthChange,
  removeSymbol,
  runIngestToCompletion,
  setMinuteSessions,
  setSymbolEnabled,
  signIn,
  signOut,
} from "../../data/admin.js"

/**
 * Data Management.
 *
 * WHO THIS IS FOR
 * Somebody who owns the product but not the infrastructure. They have no
 * Massive API key, no Supabase credentials, no terminal and no deploy access,
 * and they should not need any of them to answer "is the data current?" or to
 * do something about it when it isn't. Every control here is reachable with
 * nothing but an email and a password.
 *
 * WHAT THAT DEMANDS OF THE UI
 * Because there is no fallback to a shell, an unexplained failure here is a
 * dead end. So every error carries what went wrong AND what to do, counts are
 * read from the database rather than assumed, and a running job reports its
 * position rather than spinning. The one thing this screen must never do is
 * imply that data is fresh when it is not.
 */

const DASH = "—"

const bytes = n => {
  if (!Number.isFinite(n) || n <= 0) return DASH
  if (n < 1024) return `${n} B`
  if (n < 1024 * 1024) return `${(n / 1024).toFixed(0)} KB`
  return `${(n / (1024 * 1024)).toFixed(1)} MB`
}

const stamp = iso => {
  if (!iso) return DASH
  const d = new Date(iso)
  if (Number.isNaN(d.getTime())) return DASH
  return d.toLocaleString(undefined, {
    year: "numeric", month: "short", day: "2-digit",
    hour: "2-digit", minute: "2-digit",
  })
}

/** "3 hours ago" — the number people actually want from a timestamp. */
const ago = iso => {
  if (!iso) return null
  const ms = Date.now() - Date.parse(iso)
  if (!Number.isFinite(ms) || ms < 0) return null
  const mins = Math.floor(ms / 60000)
  if (mins < 1) return "just now"
  if (mins < 60) return `${mins} min ago`
  const hours = Math.floor(mins / 60)
  if (hours < 24) return `${hours} hour${hours === 1 ? "" : "s"} ago`
  const days = Math.floor(hours / 24)
  return `${days} day${days === 1 ? "" : "s"} ago`
}

const STATUS_TONE = {
  running: "is-running",
  completed: "is-ok",
  failed: "is-bad",
  cancelled: "is-muted",
}

export default function DataManagementPage({ location }) {
  const { toast, show, dismiss } = useToast()

  const [user, setUser] = useState(null)
  const [admin, setAdmin] = useState(false)
  const [checking, setChecking] = useState(true)

  const [status, setStatus] = useState(null)
  const [universe, setUniverse] = useState([])
  const [coverage, setCoverage] = useState([])
  const [jobs, setJobs] = useState([])
  const [settings, setSettings] = useState({})
  const [loadError, setLoadError] = useState(null)

  const [running, setRunning] = useState(false)
  const [progress, setProgress] = useState(null)
  const abortRef = useRef(null)

  /* ------------------------------------------------------------ loading -- */

  const refresh = useCallback(async () => {
    if (!isConfigured) return
    try {
      const [s, u, c, j, cfg] = await Promise.all([
        getDataStatus(),
        getUniverse(),
        getCoverage(),
        getJobs(8).catch(() => []),
        getSettings().catch(() => ({})),
      ])
      setStatus(s)
      setUniverse(u)
      setCoverage(c)
      setJobs(j)
      setSettings(cfg)
      setLoadError(null)
    } catch (error) {
      setLoadError(error)
    }
  }, [])

  useEffect(() => {
    let alive = true
    ;(async () => {
      const u = await currentUser()
      if (!alive) return
      setUser(u)
      if (u) setAdmin(await isAdmin())
      setChecking(false)
      refresh()
    })()

    const off = onAuthChange(async nextUser => {
      setUser(nextUser)
      setAdmin(nextUser ? await isAdmin() : false)
      refresh()
    })

    return () => {
      alive = false
      off()
    }
  }, [refresh])

  /*
   * While a job runs, poll so the numbers move. Ingestion is minutes long and
   * driven from this tab, so a static screen would look hung.
   */
  useEffect(() => {
    if (!running) return undefined
    const id = setInterval(refresh, 4000)
    return () => clearInterval(id)
  }, [running, refresh])

  /* ----------------------------------------------------------- handlers -- */

  const guard = fn => async (...args) => {
    try {
      await fn(...args)
    } catch (error) {
      show(
        error instanceof AdminError && error.hint
          ? `${error.message} ${error.hint}`
          : error.message || "Something went wrong."
      )
    }
  }

  const handleSignIn = guard(async event => {
    event.preventDefault()
    const form = new FormData(event.currentTarget)
    await signIn(form.get("email"), form.get("password"))
    show("Signed in.")
  })

  const handleRefreshData = guard(async () => {
    setRunning(true)
    setProgress(null)
    const controller = new AbortController()
    abortRef.current = controller

    try {
      const result = await runIngestToCompletion({
        signal: controller.signal,
        onProgress: p => setProgress(p),
      })
      await refresh()

      // The tab is holding a cached copy from before the run; without this the
      // terminal would keep showing the old data until the cache expired.
      invalidateRemoteCache()

      if (result.stopped) show("Stopped. Everything fetched so far has been saved.")
      else if (result.status === "failed") show(`Ingestion failed: ${result.error}`)
      else show(`Done — ${result.completed} of ${result.total} datasets updated.`)
    } finally {
      setRunning(false)
      abortRef.current = null
    }
  })

  const handleStop = guard(async () => {
    abortRef.current?.abort()
    await cancelIngest()
    await refresh()
    show("Cancelled. Completed datasets were kept.")
  })

  const handleToggle = guard(async (symbol, enabled) => {
    await setSymbolEnabled(symbol, enabled)
    await refresh()
  })

  const handleAdd = guard(async event => {
    event.preventDefault()
    const form = event.currentTarget
    const value = new FormData(form).get("symbol")
    const { symbol } = await addSymbol(value)
    form.reset()
    await refresh()
    show(`${symbol} added. It has no data until the next refresh.`)
  })

  const handleRemove = guard(async symbol => {
    await removeSymbol(symbol)
    await refresh()
    show(`${symbol} removed from the scan universe. Its stored history was kept.`)
  })

  const handleSessions = guard(async event => {
    event.preventDefault()
    const value = new FormData(event.currentTarget).get("sessions")
    const saved = await setMinuteSessions(value)
    await refresh()
    show(`Intraday retention set to ${saved} session${saved === 1 ? "" : "s"}. Applies to the next refresh.`)
  })

  /* --------------------------------------------------------------- views -- */

  if (!isConfigured) {
    return (
      <Shell location={location} showTicker={false}>
        <Breadcrumb items={[{ label: "Admin" }, { label: "Data Management" }]} />
        <Panel title="Data Management" subtitle="Not connected to Supabase">
          <p className="admin__prose">
            This build has no Supabase connection, so there is nothing to manage from here.
            The terminal is running on the data bundled into it at build time — every screen
            works, the figures are real, and they are as current as the last build.
          </p>
          <p className="admin__prose">
            To enable runtime refresh, set <code>GATSBY_SUPABASE_URL</code> and{" "}
            <code>GATSBY_SUPABASE_ANON_KEY</code> and rebuild. The steps are in{" "}
            <code>supabase/README.md</code>.
          </p>
        </Panel>
      </Shell>
    )
  }

  if (checking) {
    return (
      <Shell location={location} showTicker={false}>
        <Breadcrumb items={[{ label: "Admin" }, { label: "Data Management" }]} />
        <Panel title="Data Management">
          <p className="admin__prose">Checking your access…</p>
        </Panel>
      </Shell>
    )
  }

  if (!user) {
    return (
      <Shell location={location} showTicker={false}>
        <Breadcrumb items={[{ label: "Admin" }, { label: "Data Management" }]} />
        <Panel title="Sign in" subtitle="Data Management is restricted">
          <form className="admin__form admin__form--signin" onSubmit={handleSignIn}>
            <label className="admin__field">
              <span className="admin__label">Email</span>
              <input className="admin__input" type="email" name="email" required autoComplete="username" />
            </label>
            <label className="admin__field">
              <span className="admin__label">Password</span>
              <input
                className="admin__input"
                type="password"
                name="password"
                required
                autoComplete="current-password"
              />
            </label>
            <button className="admin__button admin__button--primary" type="submit">
              Sign in
            </button>
          </form>
        </Panel>
        <Toast toast={toast} onDismiss={dismiss} />
      </Shell>
    )
  }

  if (!admin) {
    return (
      <Shell location={location} showTicker={false}>
        <Breadcrumb items={[{ label: "Admin" }, { label: "Data Management" }]} />
        <Panel title="Not authorised" subtitle={user.email}>
          <p className="admin__prose">
            You are signed in, but <strong>{user.email}</strong> is not on the Data Management
            allowlist. Somebody with access can add it in Supabase under{" "}
            <code>admin_users</code>.
          </p>
          <button className="admin__button" type="button" onClick={() => signOut()}>
            Sign out
          </button>
        </Panel>
        <Toast toast={toast} onDismiss={dismiss} />
      </Shell>
    )
  }

  const lastJob = jobs[0] || null
  const activeJob = jobs.find(j => j.status === "running") || null
  const minuteSessions = settings.minute_sessions ?? 5
  const lastIngest = status?.last_ingested_at

  return (
    <Shell location={location} showTicker={false}>
      <Breadcrumb items={[{ label: "Admin" }, { label: "Data Management" }]} />

      {loadError && (
        <Panel title="Could not load" className="admin__panel--error">
          <p className="admin__prose">{loadError.message}</p>
          {loadError.hint && <p className="admin__prose admin__prose--muted">{loadError.hint}</p>}
        </Panel>
      )}

      {/* ---------------------------------------------------------- summary */}
      <Panel
        title="Data Management"
        subtitle={`Signed in as ${user.email}`}
        actions={
          <button className="admin__button" type="button" onClick={() => signOut()}>
            Sign out
          </button>
        }
      >
        <div className="admin__stats">
          <div className="admin__stat">
            <span className="admin__stat-label">Last updated</span>
            <span className="admin__stat-value">{stamp(lastIngest)}</span>
            {ago(lastIngest) && <span className="admin__stat-note">{ago(lastIngest)}</span>}
          </div>
          <div className="admin__stat">
            <span className="admin__stat-label">Universe</span>
            <span className="admin__stat-value">
              {status?.symbols_enabled ?? DASH}
              {status && status.symbols_total !== status.symbols_enabled && (
                <span className="admin__stat-sub"> of {status.symbols_total}</span>
              )}
            </span>
            <span className="admin__stat-note">symbols scanned</span>
          </div>
          <div className="admin__stat">
            <span className="admin__stat-label">Datasets stored</span>
            <span className="admin__stat-value">{status?.datasets_stored ?? DASH}</span>
            <span className="admin__stat-note">
              {status?.daily_series ?? 0} daily · {status?.minute_series ?? 0} intraday
            </span>
          </div>
          <div className="admin__stat">
            <span className="admin__stat-label">Approximate size</span>
            <span className="admin__stat-value">{bytes(status?.bytes_stored)}</span>
            <span className="admin__stat-note">uncompressed JSON</span>
          </div>
        </div>
      </Panel>

      {/* ---------------------------------------------------------- refresh */}
      <Panel
        title="Refresh data"
        subtitle="Fetches the latest bars, fundamentals and news from Massive"
      >
        <p className="admin__prose">
          The plan allows 5 API calls a minute, so a full refresh of{" "}
          {status?.symbols_enabled ?? "the"} symbols takes roughly{" "}
          <strong>{Math.ceil(((status?.symbols_enabled ?? 14) * 6 + 6) / 5)} minutes</strong>.
          It runs in stages on the server and saves as it goes — <strong>keep this tab open</strong>{" "}
          so it can continue through to the end. If you close it, nothing is lost: everything
          already fetched is kept, and starting again picks up where it stopped.
        </p>

        <div className="admin__actions">
          {!running && !activeJob && (
            <button className="admin__button admin__button--primary" type="button" onClick={handleRefreshData}>
              Refresh now
            </button>
          )}
          {(running || activeJob) && (
            <button className="admin__button admin__button--danger" type="button" onClick={handleStop}>
              Stop
            </button>
          )}
          <button className="admin__button" type="button" onClick={refresh} disabled={running}>
            Reload status
          </button>
        </div>

        {(progress || activeJob) && (
          <div className="admin__progress">
            <div className="admin__progress-bar">
              <div
                className="admin__progress-fill"
                style={{
                  width: `${Math.round(
                    (((progress?.completed ?? activeJob?.completed ?? 0) /
                      (progress?.total ?? activeJob?.total ?? 1)) || 0) * 100
                  )}%`,
                }}
              />
            </div>
            <p className="admin__progress-text">
              {progress?.completed ?? activeJob?.completed ?? 0} of{" "}
              {progress?.total ?? activeJob?.total ?? DASH} datasets
              {progress?.callsThisRun != null && (
                <> · {progress.callsThisRun} API calls, {progress.cachedThisRun} from cache</>
              )}
            </p>
          </div>
        )}
      </Panel>

      {/* --------------------------------------------------------- universe */}
      <Panel
        title="Ticker universe"
        subtitle="Which symbols the platform scans"
        flush
      >
        <table className="admin__table">
          <thead>
            <tr>
              <th>Symbol</th>
              <th>Name</th>
              <th className="is-num">Daily bars</th>
              <th className="is-num">Intraday</th>
              <th>Last bar</th>
              <th>Scanned</th>
              <th />
            </tr>
          </thead>
          <tbody>
            {universe.map(row => {
              const daily = coverage.find(c => c.symbol === row.symbol && c.kind === "daily")
              const minute = coverage.find(c => c.symbol === row.symbol && c.kind === "minute")
              return (
                <tr key={row.symbol} className={row.enabled ? "" : "is-disabled"}>
                  <td className="admin__symbol">{row.symbol}</td>
                  <td>{row.name || DASH}</td>
                  <td className="is-num">{daily?.bar_count ?? <span className="admin__pending">none yet</span>}</td>
                  <td className="is-num">{minute?.bar_count ?? DASH}</td>
                  <td>{daily?.last_bar ? stamp(daily.last_bar).split(",")[0] : DASH}</td>
                  <td>
                    <label className="admin__switch">
                      <input
                        type="checkbox"
                        checked={row.enabled}
                        onChange={e => handleToggle(row.symbol, e.target.checked)}
                      />
                      <span>{row.enabled ? "Yes" : "No"}</span>
                    </label>
                  </td>
                  <td>
                    <button
                      className="admin__button admin__button--small"
                      type="button"
                      onClick={() => handleRemove(row.symbol)}
                    >
                      Remove
                    </button>
                  </td>
                </tr>
              )
            })}
          </tbody>
        </table>

        <form className="admin__form admin__form--inline" onSubmit={handleAdd}>
          <input
            className="admin__input"
            name="symbol"
            placeholder="Add a ticker (e.g. AMD)"
            maxLength={10}
            required
          />
          <button className="admin__button" type="submit">
            Add
          </button>
        </form>
      </Panel>

      {/* -------------------------------------------------------- retention */}
      <Panel title="Intraday retention" subtitle="How many trading sessions of 1-minute data to keep">
        <p className="admin__prose">
          Intraday history is what makes the 5-day chart work at minute and 15-minute candles.
          Each session is roughly 0.6 MB across the universe, and it costs no extra API calls —
          the same request returns the whole window either way. More sessions means more storage
          and a slower first page load.
        </p>
        <form className="admin__form admin__form--inline" onSubmit={handleSessions}>
          <label className="admin__field">
            <span className="admin__label">Sessions to keep</span>
            <input
              className="admin__input admin__input--number"
              type="number"
              name="sessions"
              min="1"
              max="20"
              defaultValue={minuteSessions}
              key={minuteSessions}
            />
          </label>
          <button className="admin__button" type="submit">
            Save
          </button>
        </form>
      </Panel>

      {/* ------------------------------------------------------------- jobs */}
      <Panel title="Ingestion history" subtitle="Every run, including the ones that failed" flush>
        {jobs.length === 0 ? (
          <p className="admin__prose admin__empty">
            No ingestion has run yet. Use “Refresh now” above to fetch data for the first time.
          </p>
        ) : (
          <table className="admin__table">
            <thead>
              <tr>
                <th>Started</th>
                <th>Status</th>
                <th className="is-num">Datasets</th>
                <th className="is-num">API calls</th>
                <th>Triggered by</th>
                <th>Result</th>
              </tr>
            </thead>
            <tbody>
              {jobs.map(job => (
                <tr key={job.id}>
                  <td>{stamp(job.started_at)}</td>
                  <td>
                    <span className={`admin__status ${STATUS_TONE[job.status] || ""}`}>{job.status}</span>
                  </td>
                  <td className="is-num">
                    {job.completed}/{job.total}
                  </td>
                  <td className="is-num">
                    {job.calls_made}
                    {job.calls_cached > 0 && (
                      <span className="admin__stat-sub"> +{job.calls_cached} cached</span>
                    )}
                  </td>
                  <td>{job.triggered_by || DASH}</td>
                  <td className="admin__result">
                    {job.error ? (
                      <span className="admin__error-text">{job.error}</span>
                    ) : job.status === "running" ? (
                      job.progress || "working"
                    ) : job.failures?.length ? (
                      <details>
                        <summary>
                          {job.failures.length} issue{job.failures.length === 1 ? "" : "s"}
                        </summary>
                        <ul className="admin__failures">
                          {job.failures.slice(0, 12).map((f, i) => (
                            <li key={i}>
                              <strong>{f.job}</strong> — {f.error}
                            </li>
                          ))}
                        </ul>
                      </details>
                    ) : (
                      "clean"
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </Panel>

      {lastJob?.status === "failed" && (
        <Panel title="Last run failed" className="admin__panel--error">
          <p className="admin__prose">{lastJob.error}</p>
          <p className="admin__prose admin__prose--muted">
            Data from before this run is untouched — the terminal is still showing the last
            good ingest from {stamp(lastIngest)}.
          </p>
        </Panel>
      )}

      <Toast toast={toast} onDismiss={dismiss} />
    </Shell>
  )
}

export const Head = () => <title>Data Management · MarketScan</title>
